/**
 * Content for the product introduction.
 *
 * Steps 3–7 show screenshots of the real app in “Tạm xem theo Excel” mode
 * (src/assets/intro, regenerated by scripts/capture-intro-shots.mjs), with
 * numbered callouts. Every figure quoted in the texts lives in INTRO_SAMPLE;
 * tests/product-intro.test.mjs re-reads
 * docs/source/Nexa_Home_Recon_Dataset_Final.xlsx and the dashboard model built
 * from it, and checks each one.
 */
import { money, percent } from './dashboard-format.ts'

export type IntroStepId =
  | 'welcome'
  | 'workflow'
  | 'workbook'
  | 'review'
  | 'exceptions'
  | 'rules'
  | 'dashboard'
  | 'start'

/** A highlighted region of a screenshot: [left, top, width, height] in percent. */
export type IntroBox = [number, number, number, number]
export interface IntroCallout {
  title: string
  text: string
  box: IntroBox
}
export interface IntroShot {
  /** File name in src/assets/intro without “.webp”. */
  id: string
  label: string
  /** Shorter name for the screen switcher, when the label is long. */
  tab?: string
  alt: string
  /** Pixel size of the image (1280×800 CSS pixels captured at 2×). */
  width: number
  height: number
  callouts: IntroCallout[]
}
export interface IntroStep {
  id: IntroStepId
  /** Short label in the step list. */
  label: string
  title: string
  description: string
  /** App route opened by “Mở trong ứng dụng”. */
  route?: string
  /** Screen name in the app navigation. */
  screen?: string
  /** Screenshots of that screen, with callouts. */
  shots?: IntroShot[]
}

