export const introVarianceUSD = () => INTRO_SAMPLE.glUSD - INTRO_SAMPLE.flashUSD
/** Dashboard convention: Δ% = Δ / Sales Flash. */
export const introVarianceOfFlash = () =>
  introVarianceUSD() / INTRO_SAMPLE.flashUSD
/** Report convention (Bảng 17): Δ% = Δ / Finance GL. */
export const introVarianceOfGL = () => introVarianceUSD() / INTRO_SAMPLE.glUSD
export const introSourceRowTotal = () =>
  Object.values(INTRO_SAMPLE.sourceRows).reduce((sum, rows) => sum + rows, 0)

const count = (value: number) => new Intl.NumberFormat('vi-VN').format(value)
const usd = (value: number) => `${money(value)} USD`
