export const introStepIndex = (id: IntroStepId) =>
  INTRO_STEPS.findIndex((step) => step.id === id)
const routePath = (route: string) => route.split('?')[0]
/** Screen step showing this path of the app, or -1. */
export const introStepForPath = (pathname: string) =>
  INTRO_STEPS.findIndex(
    (step) => step.route !== undefined && routePath(step.route) === pathname,
  )

export interface IntroPhase {
  step: IntroStepId
  title: string
  summary: string
  points: string[]
}

