/**
 * The introduction opens by itself once per page load: every visit or reload
 * shows it, whatever screen the page opens on, but navigating later in the
 * same load does not. Module state (not storage) is reset by each load and
 * survives the remounts caused by starting or leaving a guided practice session.
 */
let autoOpenClaimed = false
export function claimIntroAutoOpen(): boolean {
  if (autoOpenClaimed) return false
  autoOpenClaimed = true
  return true
}
